    yhi = (((cptr.ldI16o(u, $you_uy) + 1) | 0) < 20 ? ((cptr.ldI16o(u, $you_uy) + 1) | 0) : 20);
    xlo = (((cptr.ldI16(u) - 1) | 0) > 1 ? ((cptr.ldI16(u) - 1) | 0) : 1);
